    root.innerHTML=exceptionPanel()+safeToOperatePanel()+releaseReadyPanel()+'<details id="operationsSystemHealth" style="margin-top:1.2rem;scroll-margin-top:1rem;"><summary style="cursor:pointer;font-weight:700;color:var(--bd);">Technical diagnostics — application performance by build</summary><div style="display:flex;justify-content:space-between;gap:1rem;align-items:end;flex-wrap:wrap;margin:1rem 0;"><p style="font-size:.8rem;color:var(--tl);margin:0;">For the system administrator when investigating slowness or errors. These are not daily business tasks.</p><label style="font-size:.75rem;color:var(--tl);">Period <select id="opsHealthDays" style="margin-left:.35rem;padding:.4rem;border:1px solid var(--cd);border-radius:6px;"><option value="7"'+(days===7?' selected':'')+'>Last 7 days</option><option value="30"'+(days===30?' selected':'')+'>Last 30 days</option></select></label></div><div style="padding:.8rem;margin-bottom:.75rem;border:1px solid var(--cd);background:#f7f7f4;border-radius:8px;font-size:.75rem;line-height:1.5;"><b>How to read these figures:</b> Average is the usual recorded time. Worst is the slowest recorded result. Samples are the number of times the system measured an activity. Failed means an activity did not complete normally. Client errors are privacy-safe error counts, not customer or payment details. <b>GOOD</b> is within target, <b>WATCH</b> is close to the limit, <b>ACTION</b> needs investigation, and <b>NO DATA</b> means the activity was not measured in the selected period.</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(205px,1fr));gap:.75rem;">'+METRICS.map(function(d){return card(d,agg.metrics[d.key]||{});}).join('')+'</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.75rem;margin-top:.75rem;"><div style="padding:.8rem;border-radius:8px;background:var(--cr);border:1px solid var(--cd);"><b>'+agg.samples+'</b><br><span style="font-size:.72rem;color:var(--tl);">total measurements recorded</span></div><div style="padding:.8rem;border-radius:8px;background:'+(agg.errors?'#fde8e8':'var(--cr)')+';border:1px solid var(--cd);"><b>'+agg.errors+'</b><br><span style="font-size:.72rem;color:var(--tl);">privacy-safe client errors</span></div><div style="padding:.8rem;border-radius:8px;background:var(--cr);border:1px solid var(--cd);"><b>'+esc(latest)+'</b><br><span style="font-size:.72rem;color:var(--tl);">most recent measurement received</span></div></div><div style="margin-top:1rem;background:var(--cr);border:1px solid var(--cd);border-radius:10px;padding:1rem;overflow-x:auto;"><h4 style="font-family:\'Playfair Display\',serif;color:var(--bd);margin:0 0 .65rem;">Performance history</h4><table style="width:100%;border-collapse:collapse;font-size:.78rem;"><thead><tr style="text-align:left;border-bottom:2px solid var(--cd);"><th style="padding:.5rem;">Day</th><th style="padding:.5rem;text-align:right;">Measurements</th><th style="padding:.5rem;text-align:right;">Slow or failed checks</th><th style="padding:.5rem;text-align:right;">Errors</th><th style="padding:.5rem;">Application builds measured</th></tr></thead><tbody>'+renderRows(rows)+'</tbody></table></div><p style="font-size:.72rem;color:var(--tl);margin-top:.75rem;">System administrator: investigate ACTION metrics or new client errors before publishing. These are averages and worst observations, not percentile measurements.</p></details>';
    document.getElementById('opsHealthDays').onchange=function(){days=Number(this.value)===30?30:7;load();};
